hcl:
variable "project_name" {
  type    = string
  default = "ResearchProj"
}

variable "team_count" {
  type    = number
  default = 4
}

##############################################################
# PROJECT
##############################################################
resource "lxd_project" "project" {
  name        = var.project_name
  description = "ResearchProj Custom Topology"
  config = {
    "features.storage.volumes" = true
    "features.images"          = false
    "features.profiles"        = false
    "features.storage.buckets" = true
    "features.networks"        = false
  }
}

data "lxd_project" "proj" {
  name       = var.project_name
  depends_on = [lxd_project.project]
}

##############################################################
# NETWORKS
##############################################################

resource "lxd_network" "team_wan" {
  project = data.lxd_project.proj.name
  name    = "${var.project_name}-team-wan"
  type    = "ovn"
  config = {
    "bridge.mtu"   = "1500"
    "ipv4.address" = "none"
    "network"      = "internal_link5"
  }
  depends_on = [data.lxd_project.proj]
}

resource "lxd_network" "salt_lan" {
  project = data.lxd_project.proj.name
  name    = "${var.project_name}-salt-lan"
  type    = "ovn"
  config = {
    "bridge.mtu"   = "1500"
    "ipv4.address" = "none"
    "network"      = "internal_link5"
  }
  depends_on = [data.lxd_project.proj]
}

resource "lxd_network" "team_lan" {
  count   = var.team_count
  project = data.lxd_project.proj.name
  name    = "${var.project_name}-team${count.index + 1}-lan"
  type    = "ovn"
  config = {
    "bridge.mtu"   = "1500"
    "ipv4.address" = "none"
    "network"      = "internal_link5"
  }
  depends_on = [data.lxd_project.proj]
}

resource "lxd_network" "team_dmz" {
  count   = var.team_count
  project = data.lxd_project.proj.name
  name    = "${var.project_name}-team${count.index + 1}-dmz"
  type    = "ovn"
  config = {
    "bridge.mtu"   = "1500"
    "ipv4.address" = "none"
    "network"      = "internal_link5"
  }
  depends_on = [data.lxd_project.proj]
}

locals {
  project_fw_net = concat(["CLASS_WAN", lxd_network.team_wan.name, lxd_network.salt_lan.name])
  shared_wan     = lxd_network.team_wan.name
  team_lan_names = [for n in lxd_network.team_lan : n.name]
  team_dmz_names = [for n in lxd_network.team_dmz : n.name]

  guac_net = ["GUAC_WAN", lxd_network.salt_lan.name]
  guac_wan = "GUAC_WAN"
}

variable "guac_subnet_octet" {
  type        = number
  default     = 1
  description = "Third octet for guac subnet (e.g., 1 = 10.0.1.0/24)"
}

###############################################################
# PROJECT FIREWALL & SALT
###############################################################
resource "lxd_instance" "project_fw" {
  project     = data.lxd_project.proj.name
  name        = "${var.project_name}-project-fw"
  description = "project-openwrt"
  image       = "openwrt-project"
  type        = "container"
  profiles    = ["pfsense"]

  dynamic "device" {
    for_each = toset([for i in range(length(local.project_fw_net)) : i])
    content {
      name = "eth${device.value}"
      type = "nic"
      properties = {
        network = local.project_fw_net[device.value]
      }
    }
  }
  target = "@default"

  timeouts = {
    create = "2m"
    delete = "2m"
  }

  depends_on = [data.lxd_project.proj, lxd_network.team_wan, lxd_network.salt_lan]
}

resource "lxd_instance" "project_salt" {
  project     = data.lxd_project.proj.name
  name        = "${var.project_name}-salt"
  description = "project-salt"
  type        = "virtual-machine"
  image       = "salt-master-new"
  profiles    = ["Salt-master"]

  dynamic "device" {
    for_each = toset([lxd_network.salt_lan.name])
    content {
      name = "eth0"
      type = "nic"
      properties = { network = device.value }
    }
  }

  config = {
    "cloud-init.network-config" = <<-EOF
      version: 2
      ethernets:
        enp5s0:
          dhcp4: false
          addresses:
            - 172.31.31.2/24
          routes:
            - to: 10.8.11.201
              via: 172.31.31.1
            - to: default
              via: 172.31.31.1
          nameservers:
            addresses: [172.31.31.1]
      EOF
  }

  depends_on = [lxd_network.salt_lan]
  timeouts = {
    create = "15m"
    start  = "15m"
  }
}

resource "lxd_instance" "project_guac_salt" {
  project     = data.lxd_project.proj.name
  name        = "${var.project_name}-project-guac"
  description = "project-guac-salt"
  type        = "virtual-machine"
  image       = "guac-xfce4-v02"
  profiles    = ["guac-linux"]

  dynamic "device" {
    for_each = toset([for i in range(length(local.guac_net)) : i])
    content {
      name = "eth-${device.value}"
      type = "nic"
      properties = {
        network = local.guac_net[device.value]
      }
    }
  }

  config = {
    "cloud-init.network-config" = <<-EOF
      version: 2
      ethernets:
        enp5s0:
          dhcp4: false
          addresses: 
            - 10.0.${var.guac_subnet_octet}.2/16
          routes:
            - to: default
              via: 10.0.0.1
          nameservers:
            addresses: [10.0.0.1]
        enp6s0:
          dhcp4: false
          addresses:
            - 172.31.31.3/24
          routes:
            - to: 172.31.31.1
              via: 172.31.31.1
          nameservers:
            addresses: [172.31.31.1]
      EOF
  }

  depends_on = [lxd_network.salt_lan, lxd_instance.project_fw]
}

##############################################################
# TEAM FIREWALL
##############################################################
resource "lxd_instance" "team_fw" {
  count       = var.team_count
  project     = data.lxd_project.proj.name
  name        = "team${count.index + 1}-fw"
  description = "team${count.index + 1}-fw"
  type        = "container"
  image       = "openwrt-team-new"
  profiles    = ["pfsense"]

  dynamic "device" {
    for_each = {
      for i, net in tolist([
        local.shared_wan,
        local.team_lan_names[count.index],
        local.team_dmz_names[count.index]
      ]) : i => net
    }
    content {
      name = "eth${device.key}"
      type = "nic"
      properties = {
        network = device.value
      }
    }
  }

  config = {
    "cloud-init.network-config" = <<-EOF
      version: 2
      ethernets:
        eth0:
          dhcp4: true
        eth1:
          x-openwrt-name: lan
          dhcp4: false
          addresses:
            - 192.168.1.1/24
          routes:
            - to: 192.168.1.1
              via: 192.168.1.1
          nameservers:
            addresses: [192.168.1.1]
        eth2:
          x-openwrt-name: dmz
          dhcp4: false
          addresses:
            - 10.10.0.1/24
          routes:
            - to: 10.10.0.1
              via: 10.10.0.1
          nameservers:
            addresses: [10.10.0.1]
      EOF
  }

  timeouts = {
    create = "2m"
    delete = "2m"
  }

  target = "@default"

  depends_on = [
    data.lxd_project.proj, 
    lxd_network.team_wan, 
    lxd_network.team_lan, 
    lxd_network.team_dmz
  ]
}

################################################################
# TEAM VMS
################################################################

resource "lxd_instance" "team_jumpbox" {
  count       = var.team_count
  project     = data.lxd_project.proj.name
  name        = "team${count.index + 1}-Jumpbox"
  description = "team${count.index + 1}-Jumpbox"
  type        = "virtual-machine"
  image       = "ubuntu-2204-local"
  profiles    = ["guac-linux"]

  dynamic "device" {
    for_each = {
      for i, net in tolist([local.team_lan_names[count.index]]) : i => net
    }
    content {
      name = "eth${device.key}"
      type = "nic"
      properties = {
        network = device.value
      }
    }
  }

  depends_on = [
    lxd_instance.team_fw, 
    lxd_network.team_lan
  ]
}

resource "lxd_instance" "team_gpuworker" {
  count       = var.team_count
  project     = data.lxd_project.proj.name
  name        = "team${count.index + 1}-GPUWorker"
  description = "team${count.index + 1}-GPUWorker"
  type        = "virtual-machine"
  image       = "ubuntu-2204-local"
  profiles    = ["default"]

  dynamic "device" {
    for_each = {
      for i, net in tolist([local.team_lan_names[count.index]]) : i => net
    }
    content {
      name = "eth${device.key}"
      type = "nic"
      properties = {
        network = device.value
      }
    }
  }

  depends_on = [
    lxd_instance.team_fw, 
    lxd_network.team_lan
  ]
}
